INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-an-lushan-uprising:cap-yan-anshi-fanyang-755','loc-ea36bf10f6f624664cffe9590c9bef79','reign','reign-an-lushan-uprising','范阳',NULL,755,12,16,756,1,17,9071,9072,'day','day','primary','安禄山于范阳起兵，初期军政中心在此。安军于天宝十四载十二月丁酉（十二日）攻取洛阳，按《资治通鉴》卷217与中国历代朔闰表换算为公历756-01-18，故范阳阶段止于前一日；此记录表示起兵初期的主治所，不将起兵地点等同于称帝后的正式都城。坐标为北京市区约略点，不代表已确认的唐范阳城址。','[{"label":"《资治通鉴》卷二百十七：安禄山反于范阳、十二月陷洛阳","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷217"},{"label":"中国历代朔闰表（唐、五代）：天宝十四载十二月日期换算","url":"https://ytliu0.github.io/ChineseCalendar/table_period_simp.html?period=tang5"},{"label":"故宫博物院：安禄山","url":"https://www.dpm.org.cn/lemmas/243350.html"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-an-lushan-uprising:cap-yan-anshi-luoyang-preaccession-756','loc-f7e930313c1cb946efe0973a87515dd4','reign','reign-an-lushan-uprising','洛阳',NULL,756,1,18,756,2,4,9072,9073,'day','day','primary','安军于天宝十四载十二月丁酉（十二日）攻取洛阳，按《资治通鉴》卷217与中国历代朔闰表换算为公历756-01-18；安禄山其后在此筹备并于至德元载正月称帝。此为称帝前的洛阳主治所阶段，终止于正式即位前一日。坐标为洛阳市区约略点。','[{"label":"《资治通鉴》卷二百十七：天宝十四载十二月安军陷洛阳","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷217"},{"label":"中国历代朔闰表（唐、五代）：天宝十四载十二月日期换算","url":"https://ytliu0.github.io/ChineseCalendar/table_period_simp.html?period=tang5"},{"label":"《安禄山事迹》卷下：至德元载正月乙卯朔安禄山在洛阳称帝","url":"https://zh.wikisource.org/zh-hans/安祿山事跡/卷下"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-an-lushan:cap-yan-anshi-luoyang-756','loc-f7e930313c1cb946efe0973a87515dd4','reign','reign-an-lushan','洛阳',NULL,756,2,5,757,1,29,9073,9084,'day','approximate_day','primary','安禄山于洛阳称帝并以此为政权中心；安庆绪于至德二年正月乙卯（公历757年1月30日）即位并杀安禄山，故该在位关联止于推定交接前一日。坐标为洛阳市区约略点。','[{"label":"《安禄山事迹》卷下","url":"https://zh.wikisource.org/zh-hans/安祿山事跡/卷下"},{"label":"《资治通鉴》卷219","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷219"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-an-qingxu:cap-yan-anshi-ye-757','loc-806658dc845429fdd4d9971880684542','reign','reign-an-qingxu','邺/安成府',NULL,757,10,18,759,4,6,9093,9111,'day','day','primary','安庆绪弃洛阳后退保邺郡，改邺郡为安成府；史思明杀安庆绪并接收其军后，该政权中心转至范阳。定位采用邺城遗址所在临漳县约略坐标。 地点名称原注：邺（安成府）。','[{"label":"《资治通鉴》卷219","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷219"},{"label":"《资治通鉴》卷221","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷221"}]');
