INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-ayurbarwada-yuan:cap-yuan-shangdu-15120','loc-29af81808abe96196c82242e48ea98f6','reign','reign-ayurbarwada-yuan','开平/上都',NULL,1260,1,NULL,1368,12,NULL,15120,16427,'year','month','secondary','元上都遗址的前称为开平府；定都大都后，上都保留为夏都/陪都。本记录保留既有 secondary 角色区间，古称并列为“开平/上都”。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/元上都"},{"label":"正蓝旗人民政府：元上都遗址","url":"https://www.zlq.gov.cn/zlq/mlzlq/ysdwh/ysdyz/a2734909246a4c1290578dd4d88aa954/index.shtml"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-ayushiridara-yuan:cap-yuan-helin-1370','loc-30e65be35eeafdbba3671ed1b5cc2ab0','reign','reign-ayushiridara-yuan','和林/哈拉和林',NULL,1370,1,NULL,1388,12,NULL,16440,16667,'year','month','primary','元昭宗应昌失守后退至和林；元天元帝时期和林仍为北元的政治中心。蒙古草原汗庭具有移动性，本记录表示主要都城/政治中心，不表示汗廷全年固定驻于城内。坐标为遗址WGS84。 地点名称原注：和林（哈拉和林）。','[{"label":"《明太祖实录》：元昭宗、天元帝北迁及捕鱼儿海战事","url":"https://zh.wikipedia.org/wiki/%E5%A4%A9%E5%85%83_(%E5%8C%97%E5%85%83)"},{"label":"哈拉和林古城地理位置（WGS84）","url":"https://mapcarta.com/16407530"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-ayushiridara-yuan:cap-yuan-yingchang-1369','loc-1ea20b006e9d880c15ec72dcb4e97b1e','reign','reign-ayushiridara-yuan','应昌',NULL,1369,1,NULL,1370,12,NULL,16428,16451,'year','month','temporary','元顺帝北撤后驻跸应昌；1370年应昌被明军攻克，爱猷识理达腊出逃和林。年精度记录迁入、陷落所在年；高德地点为应昌路故城墓葬区附近代表点。','[{"label":"克什克腾旗人民法院：应昌路故城遗址","url":"https://m.thepaper.cn/newsDetail_forward_27639224"},{"label":"高德地图：应昌路故城遗址","url":"https://www.amap.com/place/B0FFGSZSFZ"}]');
