INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-cao-cao-wei-gong:cap-wei-ye-213','loc-806658dc845429fdd4d9971880684542','reign','reign-cao-cao-wei-gong','邺','邺城遗址范围约略点',213,6,16,221,1,27,2561,2652,'day','day','primary','曹操受封魏公及进爵魏王后，魏国以邺为国都，建立宗庙与官属；曹丕继为魏王。称帝后初营洛阳宫，黄初元年十二月戊午幸洛阳，迁都洛阳。邺后为曹魏五都之一，本段记录其作为主都的阶段。','[{"label":"《三国志·魏书·武帝纪》","url":"https://zh.wikisource.org/zh-hans/三國志/卷01"},{"label":"《三国志·魏书·文帝纪》","url":"https://zh.wikisource.org/zh-hans/三國志/卷02"},{"label":"河北省文物考古研究院：曹操营建的邺城","url":"https://www.hbswwkg.com/2023-12/12/content_9113769.html"},{"label":"黄初纪年农历对照表","url":"https://zh.wikipedia.org/wiki/黄初"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-cao-cao-wei-wang:cap-wei-ye-213','loc-806658dc845429fdd4d9971880684542','reign','reign-cao-cao-wei-wang','邺','邺城遗址范围约略点',213,6,16,221,1,27,2561,2652,'day','day','primary','曹操受封魏公及进爵魏王后，魏国以邺为国都，建立宗庙与官属；曹丕继为魏王。称帝后初营洛阳宫，黄初元年十二月戊午幸洛阳，迁都洛阳。邺后为曹魏五都之一，本段记录其作为主都的阶段。','[{"label":"《三国志·魏书·武帝纪》","url":"https://zh.wikisource.org/zh-hans/三國志/卷01"},{"label":"《三国志·魏书·文帝纪》","url":"https://zh.wikisource.org/zh-hans/三國志/卷02"},{"label":"河北省文物考古研究院：曹操营建的邺城","url":"https://www.hbswwkg.com/2023-12/12/content_9113769.html"},{"label":"黄初纪年农历对照表","url":"https://zh.wikipedia.org/wiki/黄初"}]');
