INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-jin-r15-jin-chunqiu:cap-jin-chunqiu-yi','loc-09f3c173ba489602bebbd62253d859ec','reign','reign-jin-r15-jin-chunqiu','翼',NULL,-745,1,NULL,-669,12,NULL,-8928,-8005,'year','year','primary','晋国在西周时期已有早期都邑。曲村—天马遗址发现西周早期遗存与连续的晋侯墓地，是早期晋国政治中心；山西大学考古资料将其对应为早期晋都“翼”，翼的确切城址及始用年代仍有争议。前745年昭侯封成师于曲沃时，《史记》明确记翼为晋君都邑，曲沃桓叔、庄伯、武公随后与翼城公室并立。曲沃代翼后，《史记》记晋武公“始都晋国”，献公八年（前669年）“城聚都之，命曰绛”。翼另有翼城县南梁镇故城村等定位说法；地图取曲村—天马遗址代表点，不能视作已确认的翼城宫城坐标。','[{"label":"《史记》卷三十九·晋世家：叔虞封唐、燮改号晋与昭侯时翼都","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25208.htm"},{"label":"大连博物馆《晋国雄风》：曲沃小宗与翼都大宗、上郭古城","url":"https://www.dlmodernmuseum.com/news/detail/498.html"},{"label":"山西大学考古文博学院：西周早期晋都、燮父至文侯墓葬序列与三处都邑遗址","url":"https://archaeology.sxu.edu.cn/rcpy/yxsx/199ac6ba62514d118ef56d7d17add238.htm"},{"label":"潘明娟《圣都与俗都：晋国都城体系的演变》，《中原文化研究》2021年第2期","url":"https://www.zywhyj.cn/Uploads/PdfFile/2021-03-16/60506026c2527.pdf"},{"label":"上海博物馆《晋侯墓地》：曲村—天马早期晋都及西周晋侯墓葬","url":"https://www.shanghaimuseum.net/mu/asset2/20151230150415016/"}]');
