INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-jin-r17-jin-chunqiu:cap-jin-chunqiu-quwo','loc-823f1e50fb5d19905068bfa648831034','reign','reign-jin-r17-jin-chunqiu','曲沃',NULL,-745,1,NULL,-678,12,NULL,-8928,-8113,'year','year','primary','前745年晋昭侯封成师于曲沃，号桓叔，曲沃为其封邑及支系治所，当时晋君都翼。桓叔、庄伯、武公三世以曲沃为据点与翼公室争位；前739年桓叔应潘父之邀入晋，遭晋人反击后退回曲沃，双方公开对立；前678年武公代翼并受周王册命为晋侯。古曲沃据上郭城址及邱家庄墓群考古研究定位于今闻喜县，并非现代曲沃县。地图为高德上郭村的约略代表点，不是古城城墙或宫殿的精确位置；代翼后曲沃仍为宗庙所在地，不将祭祀中心自动延长为国君主都。 该治所属曲沃支系。','[{"label":"《史记》卷三十九·晋世家：翼都、曲沃封邑与献公都绛","url":"https://www.chinakongzi.org/kzsf/wxxs/mingpian/shiji/200705/t20070524_25208.htm"},{"label":"大连博物馆《晋国雄风》：曲沃小宗与翼都大宗、上郭古城","url":"https://www.dlmodernmuseum.com/news/detail/498.html"},{"label":"山西大学考古文博学院：天马—曲村、上郭—邱家庄与侯马新田","url":"https://archaeology.sxu.edu.cn/rcpy/yxsx/199ac6ba62514d118ef56d7d17add238.htm"},{"label":"山东大学考古讲座：田建文《唐封晋霸西东周》，古曲沃非今曲沃","url":"https://klast.sdu.edu.cn/info/1031/1673.htm"}]');
