INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-jin-r27-jin-chunqiu:cap-jin-chunqiu-xinjiang-585','loc-3d5043964471fd257a273845e0c118f8','reign','reign-jin-r27-jin-chunqiu','新田/新绛',NULL,-585,1,NULL,-349,12,NULL,-7008,-4165,'year','year','primary','晋景公于前585年迁都新田，亦称新绛，故址为今侯马晋国遗址。《左传·成公六年》记“夏四月丁丑”，属周历，未经可靠公历换算仅录年精度。地图保留侯马城市范围约略代表点，不表示具体宫城位置。','[{"label":"《左传·成公六年》：晋景公迁都新田","url":"https://zh.wikisource.org/wiki/春秋左氏傳/成公"},{"label":"大连博物馆《晋国雄风》：曲沃小宗与翼都大宗、上郭古城","url":"https://www.dlmodernmuseum.com/news/detail/498.html"},{"label":"山西大学考古文博学院：天马—曲村、上郭—邱家庄与侯马新田","url":"https://archaeology.sxu.edu.cn/rcpy/yxsx/199ac6ba62514d118ef56d7d17add238.htm"}]');
