INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-nurhaci-qing:cap-qing-shenyang-1625','loc-28fdff339f6b49d015ababa2ba5a839b','reign','reign-nurhaci-qing','沈阳/盛京',NULL,1625,1,NULL,1635,12,NULL,19500,19631,'year','month','primary','努尔哈赤于1625年迁都沈阳；皇太极于天聪八年（1634）改称“天眷盛京”，简称盛京。城市改名沿用同一都城记录，坐标为城市级约略点。','[{"label":"高德地图地理编码与地点检索","url":"https://lbs.amap.com/api/webservice/guide/api/georegeo"},{"label":"故宫博物院：努尔哈赤年表","url":"https://www.dpm.org.cn/court/lineage/226250.html"},{"label":"沈阳故宫博物院：三月初四是沈阳城的纪念日","url":"https://www.sypm.org.cn/xinwen_1/1154050075920269312.html"},{"label":"沈阳市民政局：沈阳地名沿革","url":"https://mzj.shenyang.gov.cn/xxgk/mzfc/202209/P020220919596378727460.pdf"}]');
