INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-pi-luoge-nanzhao:cap-nanzhao-tucheng-649','loc-d4daeff95fd876c3f13d7e10de236c85','reign','reign-pi-luoge-nanzhao','图城',NULL,649,1,NULL,738,12,NULL,7788,8867,'year','month','primary','巍山县政府资料称细奴逻于649年建蒙舍诏、定都图城，738年皮逻阁迁都大理太和城。图城遗址约在今大仓镇团山村山龙山于图山顶；坐标为遗址近似点，年界只按年桶表示。个别考古资料将始建年记为650年。','[{"label":"巍山彝族回族自治县人民政府：南诏古都","url":"https://www.dlweishan.gov.cn/wsxrmzf/c103396/pc/content/1983764863900553216/content_1983764863900553216.html"},{"label":"澎湃新闻：国家历史文化名城·云南巍山（遗址资料）","url":"https://www.thepaper.cn/newsDetail_forward_29300950"},{"label":"高德地图：山龙山于图山城址","url":"https://www.amap.com/place/B0FFKC2VLR"}]');
