INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-sheng-luopi-nanzhao:cap-nanzhao-tucheng-649','loc-d4daeff95fd876c3f13d7e10de236c85','reign','reign-sheng-luopi-nanzhao','图城',NULL,649,1,NULL,738,12,NULL,7788,8867,'year','month','primary','巍山县政府资料称细奴逻于649年建蒙舍诏、定都图城，738年皮逻阁迁都大理太和城。图城遗址约在今大仓镇团山村山龙山于图山顶；坐标为遗址近似点，年界只按年桶表示。个别考古资料将始建年记为650年。','[{"label":"巍山彝族回族自治县人民政府：南诏古都","url":"https://www.dlweishan.gov.cn/wsxrmzf/c103396/pc/content/1983764863900553216/content_1983764863900553216.html"},{"label":"澎湃新闻：国家历史文化名城·云南巍山（遗址资料）","url":"https://www.thepaper.cn/newsDetail_forward_29300950"},{"label":"高德地图：山龙山于图山城址","url":"https://www.amap.com/place/B0FFKC2VLR"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-shi-chaoyi:cap-yan-anshi-fanyang-secondary-759','loc-ea36bf10f6f624664cffe9590c9bef79','reign','reign-shi-chaoyi','范阳/燕京',NULL,759,4,7,763,1,30,9111,9156,'approximate_day','approximate_day','secondary','史思明称帝后改范阳为燕京；759年洛阳复入后范阳保留为燕京/后方政治中心，至史朝义败亡前后失去政权控制。末端依史朝义败亡、首级入京的时间范围标推定。坐标是北京市区约略点，不代表已确认的唐范阳城址。','[{"label":"《资治通鉴》卷221","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷221"},{"label":"《资治通鉴》卷222","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷222"}]');
