INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-shi-siming:cap-yan-anshi-fanyang-759','loc-ea36bf10f6f624664cffe9590c9bef79','reign','reign-shi-siming','范阳/燕京',NULL,759,4,7,759,9,26,9111,9116,'approximate_day','day','primary','史思明杀安庆绪后返回范阳，并于乾元二年四月在范阳称帝、改称燕京；称帝具体公历日未能据可靠历日确定，起点以安庆绪被杀日作为接续标记并标推定。759年九月史军重新进入洛阳，主都阶段止于入城前一日。坐标是北京市区约略点，不代表已确认的唐范阳城址。','[{"label":"《资治通鉴》卷221","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷221"},{"label":"北京日报：史思明建“都”范阳城","url":"https://peking.bjd.com.cn/content/s63a524c9e4b0450519f694a7.html"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-shi-siming:cap-yan-anshi-fanyang-secondary-759','loc-ea36bf10f6f624664cffe9590c9bef79','reign','reign-shi-siming','范阳/燕京',NULL,759,4,7,763,1,30,9111,9156,'approximate_day','approximate_day','secondary','史思明称帝后改范阳为燕京；759年洛阳复入后范阳保留为燕京/后方政治中心，至史朝义败亡前后失去政权控制。末端依史朝义败亡、首级入京的时间范围标推定。坐标是北京市区约略点，不代表已确认的唐范阳城址。','[{"label":"《资治通鉴》卷221","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷221"},{"label":"《资治通鉴》卷222","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷222"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-shi-siming:cap-yan-anshi-luoyang-759','loc-f7e930313c1cb946efe0973a87515dd4','reign','reign-shi-siming','洛阳/周京',NULL,759,9,27,762,10,29,9116,9153,'day','day','primary','史思明军759年九月再入洛阳后，以洛阳为周京；762年唐军收复洛阳，止于失守前一日。坐标为洛阳市区约略点。 地点名称原注：洛阳（周京）。','[{"label":"《资治通鉴》卷221","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷221"},{"label":"《资治通鉴》卷222","url":"https://zh.wikisource.org/zh-hans/資治通鑑_(胡三省音注)/卷222"}]');
