INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-sima-zhong-restored:cap-jin-west-changan-304','loc-bdbe217d58d2becb8018927319f45679','reign','reign-sima-zhong-restored','长安',NULL,304,1,NULL,306,6,10,3648,3677,'year','day','temporary','永安元年（304）张方挟持晋惠帝司马衷及公卿至长安，司马颙以征西府为宫；惠帝于306年6月11日还洛阳。洛阳留台仍承制行事，故此处记长安为短期朝廷实际驻地（行在），洛阳仍保留西晋京师都城记录。起点按年精度表示，史载为农历十一月，未将农历日直接换作公历月日。','[{"label":"《晋书·惠帝纪》","url":"https://www.shidianguji.com/book/LS0005/chapter/LS0005_52"},{"label":"陕西省地方志：西安市志","url":"https://dfz.shaanxi.gov.cn/zslm/fzzlk/xbsxsxz/xbsxz/xas_16198/201405/P020240923625160882829.pdf"},{"label":"中国人民大学清史研究所：先秦至明代地理研究（引《西安历史地图集》）","url":"https://iqh.ruc.edu.cn/old/zglsdlyj/lsdl_lzjj/xqzmddlyj/490272705243483b96edc6a7eea546cd.htm"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-sima-zhong-restored:cap-jin-west-luoyang-266','loc-f7e930313c1cb946efe0973a87515dd4','reign','reign-sima-zhong-restored','洛阳',NULL,249,2,5,304,12,NULL,2989,3659,'day','month','primary','249年高平陵之变后，洛阳为司马氏执掌魏廷的政治中心；263年晋公、264年晋王府及266年西晋帝国均在洛阳。侯爵封邑不作为都城。西晋建都洛阳至304年被张方挟往长安前，迁出记于农历十一月，保留原年精度边界。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/西晋"},{"label":"《晋书·宣帝纪》","url":"https://zh.wikisource.org/zh-hans/晉書/卷001"},{"label":"《晋书·景帝纪、文帝纪》","url":"https://zh.wikisource.org/zh-hans/晉書/卷002"},{"label":"《晋书·武帝纪》","url":"https://zh.wikisource.org/zh-hans/晉書/卷003"},{"label":"《三国志·三少帝纪》","url":"https://zh.wikisource.org/zh-hans/三國志/卷04"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-sima-zhong-restored:cap-jin-west-luoyang-306','loc-f7e930313c1cb946efe0973a87515dd4','reign','reign-sima-zhong-restored','洛阳',NULL,306,6,11,313,6,11,3677,3761,'day','day','primary','晋惠帝于306年6月11日还洛阳后，洛阳恢复为西晋都城；313年6月12日司马业在长安即位，西晋朝廷迁至长安，洛阳都城阶段止于前一日。','[{"label":"《晋书·惠帝纪》：304年西迁及306年奉帝还洛阳","url":"https://www.shidianguji.com/book/LS0005/chapter/LS0005_52"},{"label":"《晋书》卷五·愍帝纪","url":"https://www.shidianguji.com/book/HY3000/chapter/1kr3u6p11dkwr"},{"label":"维基百科：西晋","url":"https://zh.wikipedia.org/wiki/西晋"},{"label":"晋惠帝（归洛阳日期换算）","url":"https://zh.wikipedia.org/wiki/晋惠帝"}]');
