INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-sun-hao:cap-wu-jianye-222','loc-248ff7be823a2f4964045f586e347281','reign','reign-sun-hao','建业',NULL,229,1,NULL,265,12,NULL,2748,3191,'year','year','primary','孙权229年秋九月由武昌迁都建业，至265年孙皓迁武昌前建业为主都。229年迁都月为原历九月，不是公历1月；本记录起点按可确定公历年展示。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/东吴"},{"label":"《三国志·吴书·吴主传》","url":"https://zh.wikisource.org/zh-hans/三國志/卷47"},{"label":"南京市地方志：东吴政权两次迁都南京","url":"https://dfz.nanjing.gov.cn/gzdt/202403/t20240315_4186987.html"},{"label":"黄龙纪年农历对照表","url":"https://zh.wikipedia.org/wiki/黄龙_(孙吴)"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-sun-hao:cap-wu-jianye-266','loc-248ff7be823a2f4964045f586e347281','reign','reign-sun-hao','建业',NULL,266,1,NULL,280,12,NULL,3192,3371,'year','year','primary','孙权222年建立独立吴政权时都武昌（今鄂州），229年称帝后迁建业；此记录不把建业提前到222年。孙皓265年迁武昌、266年复还，建业阶段另分时记录。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/东吴"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-sun-liang:cap-wu-jianye-222','loc-248ff7be823a2f4964045f586e347281','reign','reign-sun-liang','建业',NULL,229,1,NULL,265,12,NULL,2748,3191,'year','year','primary','孙权229年秋九月由武昌迁都建业，至265年孙皓迁武昌前建业为主都。229年迁都月为原历九月，不是公历1月；本记录起点按可确定公历年展示。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/东吴"},{"label":"《三国志·吴书·吴主传》","url":"https://zh.wikisource.org/zh-hans/三國志/卷47"},{"label":"南京市地方志：东吴政权两次迁都南京","url":"https://dfz.nanjing.gov.cn/gzdt/202403/t20240315_4186987.html"},{"label":"黄龙纪年农历对照表","url":"https://zh.wikipedia.org/wiki/黄龙_(孙吴)"}]');
INSERT INTO "location_mapping" ("id","location_id","kind","external_id","historical_name","spatial_precision","start_year","start_month","start_day","end_year","end_month","end_day","start_abs","end_abs","start_confidence","end_confidence","role","note","links") VALUES ('map-reign:reign-sun-quan-wu-wang:cap-wu-wuchang-221','loc-wu-wuchang-ezhou','reign','reign-sun-quan-wu-wang','武昌','遗址POI约略点，非宫殿或完整城墙边界',221,1,NULL,229,12,NULL,2652,2759,'year','year','primary','孙权221年由公安徙治鄂，改名武昌，营筑城郭，受封吴王后以此为都；229年在武昌称帝，同年秋九月迁都建业。古武昌城为今湖北鄂州吴王城遗址，非今武汉市武昌区。','[{"label":"《三国志·吴书·吴主传》","url":"https://zh.wikisource.org/zh-hans/三國志/卷47"},{"label":"鄂州市民政局：鄂州市最古老地名—吴王城","url":"https://mzj.ezhou.gov.cn/ztzl/dmpc/201602/t20160224_208688.html"},{"label":"南京市地方志：东吴政权两次迁都南京","url":"https://dfz.nanjing.gov.cn/gzdt/202403/t20240315_4186987.html"}]');
